Tool schema:
{
  "name": "schedule_shifts",
  "description": "Schedule staff shifts for a team over a period. No entry of `shifts` may have `end_hour` less than or equal to `start_hour`.",
  "parameters": {
    "type": "object",
    "properties": {
      "period_end": {"type": "string", "format": "date", "description": "Last day of the period."},
      "min_staff": {"type": "integer", "minimum": 1, "maximum": 6, "description": "Minimum number of staff members per shift."},
      "overtime_ok": {"type": "boolean", "description": "Whether overtime is allowed."},
      "memo": {"type": "string", "description": "Short memo for the records."},
      "language": {"type": "string", "enum": ["en", "de", "fr", "nl"], "description": "Language of the confirmation, as a two-letter ISO 639-1 code."},
      "shifts": {
        "type": "array",
        "description": "Shifts of the rota.",
        "minItems": 1,
        "maxItems": 5,
        "items": {
          "type": "object",
          "required": ["employee_id", "day", "start_hour", "end_hour"],
          "additionalProperties": false,
          "properties": {
            "employee_id": {"type": "string", "description": "Employee who works the shift."},
            "day": {"type": "string", "format": "date", "description": "Day of the shift."},
            "start_hour": {"type": "integer", "minimum": 0, "maximum": 23, "description": "Hour at which the shift starts."},
            "end_hour": {"type": "integer", "minimum": 1, "maximum": 24, "description": "Hour at which the shift ends."},
            "role": {"type": "string", "enum": ["cashier", "driver", "cook", "guard"], "description": "Role during the shift."}
          }
        }
      }
    },
    "required": ["period_end", "min_staff", "memo", "language", "shifts"],
    "additionalProperties": false
  }
}

