Tool schema:
{
  "name": "file_claim",
  "description": "File an insurance claim with a list of cost items. `incident_date` has to be the same day as `filed_date` or earlier. `claimed_total` is computed from `expenses`: the sum of `amount` for all entries.",
  "parameters": {
    "type": "object",
    "properties": {
      "claim_ref": {"type": "string", "description": "Reference of the claim."},
      "incident_date": {"type": "string", "format": "date", "description": "Day on which the damage occurred."},
      "filed_date": {"type": "string", "format": "date", "description": "Day on which the claim is filed."},
      "cost_centre": {"type": "string", "description": "Cost centre to charge."},
      "region": {"type": "string", "enum": ["north", "south", "east", "west", "central"], "description": "Sales region."},
      "claimant": {
        "type": "object",
        "description": "Person who files the claim.",
        "required": ["name"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "description": "Full name."},
          "email": {"type": "string", "description": "E-mail address."},
          "phone": {"type": "string", "description": "Phone number."}
        }
      },
      "expenses": {
        "type": "array",
        "description": "Cost items of the claim.",
        "minItems": 1,
        "maxItems": 6,
        "items": {
          "type": "object",
          "required": ["item_ref", "kind", "amount"],
          "additionalProperties": false,
          "properties": {
            "item_ref": {"type": "string", "description": "Reference of the cost item."},
            "kind": {"type": "string", "enum": ["travel", "repair", "medical", "other"], "description": "Kind of cost."},
            "amount": {"type": "number", "minimum": 1, "maximum": 2000, "description": "Amount of the cost item."},
            "receipt": {"type": "boolean", "description": "Whether a receipt is attached."}
          }
        }
      },
      "currency": {"type": "string", "enum": ["EUR", "USD", "GBP"], "description": "Currency of all prices and amounts of the entries."},
      "claimed_total": {"type": "number", "minimum": 0, "description": "Total of all cost items in the given currency."}
    },
    "required": ["claim_ref", "incident_date", "filed_date", "region", "claimant", "expenses", "currency", "claimed_total"],
    "additionalProperties": false
  }
}

