  "name": "create_order",
  "description": "Create a customer order with one or more line items. `discount_code` may be used only when `channel` equals 'partner'. Give either `contact.email` or `contact.phone`, but not both and not neither. `total` must equal the sum, over all entries of `items`, of `quantity` times `unit_price`.",
  "parameters": {
    "type": "object",
    "properties": {
      "customer_id": {"type": "string", "description": "Customer who orders."},
      "channel": {"type": "string", "enum": ["web", "partner", "store", "agent"], "description": "Sales channel of the order."},
      "discount_code": {"type": "string", "description": "Discount code of the customer."},
      "cost_centre": {"type": "string", "description": "Cost centre to charge."},
      "approver": {"type": "string", "description": "Person who approved the request."},
      "region": {"type": "string", "enum": ["north", "south", "east", "west", "central"], "description": "Sales region."},
      "urgent": {"type": "boolean", "description": "Whether the request is urgent."},
      "memo": {"type": "string", "description": "Short memo for the records."},
      "contact": {
        "type": "object",
        "description": "Person to contact about the order.",
        "required": ["name"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "description": "Full name."},
          "email": {"type": "string", "description": "E-mail address."},
          "phone": {"type": "string", "description": "Phone number."}
        }
      },
      "items": {
        "type": "array",
        "description": "Order lines.",
        "minItems": 1,
        "maxItems": 8,
        "items": {
          "type": "object",
          "required": ["sku", "quantity", "unit_price"],
          "additionalProperties": false,
          "properties": {
            "sku": {"type": "string", "description": "Catalogue number of the article."},
            "quantity": {"type": "integer", "minimum": 1, "maximum": 20, "description": "Number of units."},
            "unit_price": {"type": "number", "minimum": 1, "maximum": 500, "description": "Price of one unit."},
            "boxed": {"type": "boolean", "description": "Whether this line is packed in a box of its own."}
          }
        }
      },
      "currency": {"type": "string", "enum": ["EUR", "USD", "GBP"], "description": "Currency of all prices and amounts of the entries."},
      "total": {"type": "number", "minimum": 0, "description": "Total of all order lines in the currency of the order."}
    },
    "required": ["customer_id", "channel", "cost_centre", "region", "contact", "items", "currency", "total"],
    "additionalProperties": false
  }
}

